function stripValue(nums: number[], val: number): void {
  let i = 0, n = nums.length;
  while (i < n) {
    if (nums[i] === val) {
      nums[i] = nums[n - 1];
      n--; // check slot i again: the moved value may also be val
    } else i++;
  }
  nums.length = n;
}

