class Solution:
    def stripValue(self, nums: List[int], val: int) -> None:
        i, n = 0, len(nums)
        while i < n:
            if nums[i] == val:
                nums[i] = nums[n - 1]
                n -= 1  # check slot i again: the moved value may also be val
            else:
                i += 1
        del nums[n:]

